INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f9ed5e91-2888-4f7e-8499-85f71ffe2101', '051b209e-9985-44da-a832-ca884783cb98', 3, 'A Força do Hábito', NULL, '{"intro": "H\u00e1bitos s\u00e3o os trilhos sobre os quais nossa vida corre.", "prayer": "Pe\u00e7a const\u00e2ncia para as pequenas coisas.", "practice": "Inicie hoje um novo micro-h\u00e1bito positivo.", "reflection": "Somos o que fazemos repetidamente.", "journal_prompt": "Quais trilhos voc\u00ea est\u00e1 construindo hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;